fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    assert!(s1.len() == s2.len() && s2.len() == s3.len());

    let n = s1.len();
    let mut res = Vec::with_capacity(n * 3);

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}